        print(f'  #{j}: {img.get(\"name\",\"?\")} 0x{addr:x} (+0x{offset:x})')
else:
    print('No lastExceptionBacktrace')

# Check all threads for .NET frames
print('\n=== OTHER THREADS WITH .NET FRAMES ===')
